from access import Authenticator, Sessions

def compact(doc):
    return json.dumps(doc, ensure_ascii=False, separators=(",", ":"))

def pool_entry(pool_id, cidr, reserved=(), static=()):
    return {"标识": pool_id, "CIDR": cidr, "保留": list(reserved),
            "静态": [[u, ip] for u, ip in static]}

def v6_entry(pool_id, agg, deleg, reserved=(), static=()):
    return {"标识": pool_id, "聚合前缀": agg, "委派长度": deleg,
            "保留": list(reserved), "静态": [[u, p] for u, p in static]}

def template_entry(tid):
    return {"标识": tid, "限速": 1, "突发": 0, "配额": 10**9,
            "周期毫秒": 0, "会话上限": 0, "排队优先级": 0, "超限": "拒绝"}

cfg = {
    "版本": 12,
    "会话": {"总数": 100, "每用户": 10, "空闲毫秒": 50000, "租期毫秒": 1000},
    "地址池": [pool_entry("default", "10.0.0.0/28"), pool_entry("p2", "10.1.0.0/28", static=[("bob", "10.1.0.5")])],
    "模板": [template_entry("dual")],
    "用户模板": [["alice", "dual"], ["bob", "dual"]],
    "容量": {"队列上限": 1024, "最大等待毫秒": 0, "队满策略": "拒绝"},
    "认证": {"最大失败": 3, "锁定毫秒": 10**9, "重试基数毫秒": 0, "重试上限毫秒": 0},
    "模板地址池": [],
    "IPv6 前缀池": [
        v6_entry("v6a", "2001:db8::/48", 56),
        v6_entry("v6b", "2001:db8:1::/48", 56, static=[("bob", "2001:db8:1:500::/56")]),
    ],
    "模板 IPv6 池": [["dual", ["v6a", "v6b"]]],
}
auth = Authenticator(3, 10**9)
for u in ("alice", "bob"):
    auth.add(u, "pw")
s = Sessions(auth, 100, 10, 50000, pool=("10.0.0.0/30", (), ()), lease_ms=1000)
s.load_config(compact(cfg))
s.do("k1", "建立", "s1", ("alice", "pw"), 0)
out = s.do("k2", "双栈迁移", "s1", ("p2", "v6b", "pw"), 500)
