assert doc["目标池"] == "p2" and doc["目标地址"] == "10.1.0.1"
assert doc["租期"] == 1500 and doc["IPv6租期"] == 1500
assert doc["原IPv6前缀"] == "2001:db8::/56" and doc["目标IPv6前缀"] == "2001:db8:1::/56"
# bob: static preferences both sides
s.do("k3", "建立", "s2", ("bob", "pw"), 0)
out2 = json.loads(s.do("k4", "双栈迁移", "s2", ("p2", "v6b", "pw"), 500))
assert out2["目标地址"] == "10.1.0.5", out2["目标地址"]
assert out2["目标IPv6前缀"] == "2001:db8:1:500::/56", out2["目标IPv6前缀"]
# replay byte-identical
assert s.do("k2", "双栈迁移", "s1", ("p2", "v6b", "pw"), 500) == out
