        raise AssertionError("expected StateError %r" % (args,))
    except access.StateError:
        pass
# unknown pools
try:
    s.do("kx", "双栈迁移", "s1", ("nope", "v6a", "pw"), 600)
    raise AssertionError
except KeyError:
    pass
try:
    s.do("ky", "双栈迁移", "s1", ("default", "nope", "pw"), 600)
    raise AssertionError
except KeyError:
    pass
# param types
try:
    s.do("kt", "双栈迁移", "s1", ["p2", "v6b", "pw"], 600)
    raise AssertionError
except TypeError:
    pass
try:
    s.do("kt2", "双栈迁移", "s1", ("p2", "v6b"), 600)
    raise AssertionError
except ValueError:
    pass
